		int q = linesp.nextInt();

		Queue<Process> Q = new ArrayDeque<>();

		for (int c10=0; c10<BD; c10++) {
			Q.add(new Process(linesp.next(), linesp.nextInt()));
		}

		int seg = 0;
		while (!Q.isEmpty()) {
			Process p = Q.poll();
			if (p.time<=q) {
				seg += p.time;
				System.out.println(p.name + " " + seg);
			} else {
				seg += q;
				p.time -= q;
				Q.add(p);
			}
		}

		linesp.close();
	}

