		for(int mrad = 0; mrad < N; mrad ++) {
			A.add(max_1.nextInt());
		}

		Collections.sort(A);
		int distance = 0;
		for(int mysum2 = 0; mysum2 < A.size(); mysum2 ++) {
			if(mysum2 == 0) {
				distance += A.get(mysum2);
