		int longest = A.get(0) + issafe - A.get(A.size() - 1);

		for(int Winner = 1; Winner < A.size(); Winner ++) {
			longest = Math.max(longest, A.get(Winner) - A.get(Winner - 1));
		}

		System.out.println(distance - longest);
	}
}

