	public static void solve(FastScanner sc, PrintWriter out){
		int n = sc.nextInt();
		int x = sc.nextInt();

		int[] tax_a = new int[n];

		long res = 0;

		for(int sBuffer = 0; sBuffer < n; sBuffer++) {
