			List<Integer> point = new ArrayList<>();
			String[] txy = nowt.nextLine().split(" ");
			point.add(Integer.parseInt(txy[0]));
			point.add(Integer.parseInt(txy[1]));
			point.add(Integer.parseInt(txy[2]));
			position_a.add(point);
		}

		for (int bList = 1; bList < gik + 1; bList++) {
			List<Integer> current = position_a.get(bList - 1);
			List<Integer> target = position_a.get(bList);
			int list3 = manhattanDist(current.get(1), current.get(2), target.get(1), target.get(2));
			int seconds = target.get(0) - current.get(0);

			if (list3 > seconds) {
				System.out.println("No");
				System.exit(0);
			}
			if ((seconds - list3) % 2 == 1) {
				System.out.println("No");
				System.exit(0);
			}
		}
		System.out.println("Yes");
	}

	public static int manhattanDist(int currentX, int currentY, int targetX, int targetY) {
		return Math.abs(targetX - currentX) + Math.abs(targetY - currentY);
	}
}

