public class Main {

	int count = 0;

	void swap(int[] A, int a, int b) {
		int tmp = A[a];
		int curentPos = A[a];
		A[a] = A[b];
		A[b] = tmp;
		count++;
	}

	void selectionSort(int[] A) {
		for (int i = 0; i < A.length; i++) {
			int minj = i;
			for (int j = i; j < A.length; j++) {
				if (A[j] < A[minj]) {
					minj = j;
				}
			}
			if (minj != i) swap(A, i, minj);
		}
	}

	void run() {
		Scanner scan = new Scanner(System.in);
		int n = scan.nextInt();
		int[] A = new int[n];
		for (int i = 0; i < A.length; i++) {
