	public static void main(String[] hashSetb) throws IOException{
		// TODO Auto-generated method stub

		BufferedReader nyureal = new BufferedReader(new InputStreamReader(System.in));


	    int stoneCount = Integer.parseInt(nyureal.readLine());
        String str[] = nyureal.readLine().split(" ");
	    int stones[] = new int[stoneCount];

	    for(int i=0;i<stoneCount; i++) stones[i] = Integer.parseInt(str[i]);

	     int dp[]  = new int[stoneCount + 1];

	     for(int i=0; i<=stoneCount; i++) dp[i] = -1;

	    int minimumIncurred = solve(stones, 0, stoneCount, dp);

	    System.out.println(minimumIncurred);



	}

	public static int solve(int floor_num[], int exchange, int stoneCount, int dp[])
	{

		if(exchange==stoneCount-1)
			return 0;

		if(dp[exchange] != -1)
			return dp[exchange];
		int first = Integer.MAX_VALUE;
		int numMonsters = Integer.MAX_VALUE;
		if(exchange+1<stoneCount) 
		first = Math.abs(floor_num[exchange] - floor_num[exchange+1])+solve(floor_num, exchange+1, stoneCount, dp);
		if(exchange+2<stoneCount)
		numMonsters = Math.abs(floor_num[exchange] - floor_num[exchange+2])+ solve(floor_num, exchange+2, stoneCount, dp);
		dp[exchange] = Math.min(first, numMonsters);
		return Math.min(first, numMonsters);	
	}

}

