class SelectionSort{
    int[] selSort;
    public SelectionSort(int[] selSort){
        this.selSort = selSort;
    }

    int count = 0;
    public void changeOfSNum(){
        int maxNum = 0;
        int flag = 0;
        for(int intTategoukei = 0, j; intTategoukei < selSort.length; intTategoukei++){
            maxNum = selSort[intTategoukei];
            j = intTategoukei + 1;
            while(j < selSort.length){
                if(selSort[j] < selSort[intTategoukei]){
                    selSort[intTategoukei] = selSort[j];
                    flag = j;
                }
                j++;
            }
            if(maxNum != selSort[intTategoukei]){
                selSort[flag] = maxNum;
                count++;
            }
        }
    }

    public void outPutOfSNum(){
        for(int marblesPlace = 0; marblesPlace < selSort.length; marblesPlace++){
            if(marblesPlace == 0){
                System.out.print(selSort[marblesPlace]);
                continue;
            }
            System.out.print(" " + selSort[marblesPlace]);
        }
        System.out.print("\n");
    }

    public void outPutCount(){
        System.out.println(count);
    }
}

