public class Main {
    static int[] h;
    static int n;
    static int k;
    static Integer[] dp;
    public static void main(String[] args) {
        InputReader reader = new InputReader(System.in);
        n = reader.nextInt();
        k = reader.nextInt();
        h = new int[n];
        dp = new Integer[n];
        for(int s_1=0;s_1<n;s_1++){
            h[s_1] = reader.nextInt();
        }
        System.out.println(frogJump(0));
    }

    static int frogJump(int inputRowAndCol){
        if(inputRowAndCol == n-1){
            return 0;
        }
        if(dp[inputRowAndCol]!=null){
            return dp[inputRowAndCol];
        }
        int minCost = Integer.MAX_VALUE;
        for(int storage=1;storage<=k;storage++) {
            if (inputRowAndCol + storage < n) {
                int cost = Math.abs(h[inputRowAndCol] - h[inputRowAndCol + storage]) + frogJump(inputRowAndCol + storage);
                minCost = Math.min(minCost, cost);
            }
        }
        dp[inputRowAndCol] = minCost;
        return minCost;
    }
}

