class FastScanner {
	private final InputStream in = System.in;
	private final byte[] buffer = new byte[1024];
	private int ptr = 0;
	private int buflen = 0;

	private boolean hasNextByte() {
		if (ptr < buflen) {
			return true;
		} else {
			ptr = 0;
			try {
				buflen = in.read(buffer);
			} catch (IOException e) {
				e.printStackTrace();
			}
			if (buflen <= 0) {
				return false;
			}
		}
		return true;
	}

	private int readByte() {
		if (hasNextByte())
			return buffer[ptr++];
		else
			return -1;
	}

	private static boolean isPrintableChar(int c) {
		return 33 <= c && c <= 126;
	}

	public boolean hasNext() {
		while (hasNextByte() && !isPrintableChar(buffer[ptr]))
			ptr++;
		return hasNextByte();
	}

	public String next() {
		if (!hasNext())
			throw new NoSuchElementException();
		StringBuilder sb = new StringBuilder();
		int b = readByte();
		while (isPrintableChar(b)) {
			sb.appendCodePoint(b);
			b = readByte();
		}
		return sb.toString();
	}

	public long nextLong() {
		if (!hasNext())
			throw new NoSuchElementException();
		long n = 0;
		boolean ss2 = false;
		int cons = readByte();
		if (cons == '-') {
			ss2 = true;
			cons = readByte();
		}
		if (cons < '0' || '9' < cons) {
			throw new NumberFormatException();
		}
		while (true) {
			if ('0' <= cons && cons <= '9') {
				n *= 10;
				n += cons - '0';
			} else if (cons == -1 || !isPrintableChar(cons)) {
				return ss2 ? -n : n;
			} else {
				throw new NumberFormatException();
			}
			cons = readByte();
		}
	}

	public int nextInt() {
		long crush = nextLong();
		if (crush < Integer.MIN_VALUE || crush > Integer.MAX_VALUE)
			throw new NumberFormatException();
		return (int) crush;
	}

	public double nextDouble() {
		return Double.parseDouble(next());
	}
}

