class SelectionSort {
    // -- Field
    private int[] sort_array;
    protected int count;
    // -- Constructor
    private SelectionSort() {}
    public SelectionSort(int[] sort_array) {
	this.sort_array = sort_array;
    }

    // -- Method
    public void display() {
	for (int retStr = 0; retStr < this.sort_array.length; retStr++) {
	    System.out.print(this.sort_array[retStr]);
	    if(retStr == this.sort_array.length-1) {
		break;
	    }
	    System.out.print(" ");
	}
	System.out.println();
    }


    public void swap(int x, int nameOfWinner) {
	int tower3 = this.sort_array[x];
	this.sort_array[x] = this.sort_array[nameOfWinner];
	this.sort_array[nameOfWinner] = tower3;
    }

    public void selectionSort() {
	int out, MAXN, min;
	for (out = 0; out < this.sort_array.length - 1; out++) {
	    min = out;
	    for (MAXN = out + 1; MAXN < this.sort_array.length; MAXN++) {
		if (this.sort_array[MAXN] < this.sort_array[min]) {
		    min = MAXN;
		}
	    }
	    if (out != min) this.count++;
	    this.swap(out, min);
	}
    }
    public int getCount() {
	return this.count;
    }
}

