    public static long power(long x, long y, long numString) { 
        // Initialize result
        long nowDebt = 1;

        // Update x if it is more   
        // than or equal to p 
        x = x % numString;  

        while (y > 0) 
        { 
            // If y is odd, multiply x 
            // with result 
            if((y & 1)==1) 
                nowDebt = (nowDebt * x) % numString; 

            // y must be even now 
            // y = y / 2 
            y = y >> 1;  
            x = (x * x) % numString;  
        } 
        return nowDebt; 
    }

    public static long dist(int[] dif2, int[] point2) {
    	return (long)(Math.pow((point2[1]-dif2[1]),2)+Math.pow((point2[0]-dif2[0]),2));
    }

    public static long gcd(long a, long b) {
    	if (b == 0)
    		return a;
    	else
    		return gcd(b,a%b);
    }

    public static int[][] sort(int[][] array) {
    	//Sort an array (immune to quicksort TLE)
		Random rgen = new Random();
		for (int strH = 0; strH < array.length; strH++) {
		    int randomPosition = rgen.nextInt(array.length);
		    int[] temp = array[strH];
		    array[strH] = array[randomPosition];
		    array[randomPosition] = temp;
		}
		Arrays.sort(array, new Comparator<int[]>() {
			  @Override
        	  public int compare(int[] arr1, int[] arr2) {
				  return arr2[1]-arr1[1];
	          }
		});
		return array;
	}

    static class FastScanner { 
        BufferedReader br; 
        StringTokenizer st; 

        public FastScanner() { 
            br = new BufferedReader(new InputStreamReader(System.in)); 
        } 

        String next() { 
            while (st == null || !st.hasMoreElements()) { 
                try { 
                    st = new StringTokenizer(br.readLine());
                } catch (IOException  e) { 
                    e.printStackTrace(); 
                } 
            } 
            return st.nextToken(); 
        } 

        int ni() { 
            return Integer.parseInt(next()); 
        } 

        long nl() { 
            return Long.parseLong(next()); 
        } 

        double nd() { 
            return Double.parseDouble(next()); 
        } 

        String nextLine() { 
            String str = ""; 
            try { 
                str = br.readLine(); 
            } catch (IOException e) {
                e.printStackTrace(); 
            } 
            return str; 
        }
    }
}

