    static boolean solve() {
        for (int a0 = 0; a0 <= 100; a0++) {
            if( isOk(a0) ) {
                return true;
            }
        }
        return false;
    }

    static boolean isOk(int x2) {
        int[] b = new int[3];
        for (int i = 0; i < 3; i++) {
            b[i] = C[0][i] - x2;
        }
        int[] a = new int[3];
        a[0] = x2;
        a[1] = C[1][0] - b[0];
        a[2] = C[2][0] - b[0];

        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                if( a[i] + b[j] != C[i][j] ) return false;
            }
        }
        return true;
    }

    @SuppressWarnings("unused")
    static class FastScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream juelSize) {
            reader = new BufferedReader(new InputStreamReader(juelSize));
            tokenizer = null;
        }

        String next() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException sAry) {
                    throw new RuntimeException(sAry);
                }
            }
            return tokenizer.nextToken();
        }

        String nextLine() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    return reader.readLine();
                } catch (IOException taroScore) {
                    throw new RuntimeException(taroScore);
                }
            }
            return tokenizer.nextToken("\n");
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        int[] nextIntArray(int L1) {
            int[] a = new int[L1];
            for (int i = 0; i < L1; i++)
                a[i] = nextInt();
            return a;
        }

        long[] nextLongArray(int n) {
            long[] a = new long[n];
            for (int i = 0; i < n; i++)
                a[i] = nextLong();
            return a;
        }
    }
}

