public class Main {
    static final int INF = Integer.MAX_VALUE;

    static int mergeSort(int[] a,int [] c, int begin, int end)
    {
        int inversion=0;
        if(begin < end)
        {
            inversion=0;
            int tur = (begin + end) >>1;
            inversion+= mergeSort(a,c, begin, tur);
            inversion+=mergeSort(a, c,tur + 1, end);
            inversion+=merge(a,c, begin, tur, end);
        }
        return inversion;
    }


    static int  merge(int[] a,int[]c, int b, int mid, int strPtr)
    {
        int n1 = mid - b + 1;
        int n2 = strPtr - mid;
        int[] L = new int[n1+1], R = new int[n2+1];
        int[] L1 = new int[n1+1], R1 = new int[n2+1];
        //inversion
        int inversion=0;

        for(int numOfHouses = 0; numOfHouses < n1; numOfHouses++) {
            L[numOfHouses] = a[b + numOfHouses];
            L1[numOfHouses] = c[b + numOfHouses];
        }
        for(int tx = 0; tx < n2; tx++)  {
            R[tx] = a[mid + 1 + tx];
            R1[tx] = c[mid + 1 + tx];
        }
        L[n1] = R[n2] = INF;

        for(int k = b, i = 0, j = 0; k <= strPtr; k++)
            if(L[i] <= R[j]){
                a[k] = L[i];
                c[k] = L1[i++];
            }

            else
            {
                a[k] = R[j];
                c[k] = R1[j++];
                inversion=inversion+(n1-i);

            }
        return inversion;

    }

    static int []c;
    static int[] v;
    static long gcd(long a, long b)
    {
        if (b == 0)
            return a;
        return gcd(b, a % b);
    }

