public class Main {

	public static void main(String[] shuru) throws IOException {

		//	Scanner sc = new Scanner(System.in);//入力
		BufferedReader String_spot = new BufferedReader(new InputStreamReader(System.in));

		//渡される定数
		String[] vecnm = (String_spot.readLine()).split("\\s");//入力数値をスペース前後で分割
		int n = Integer.parseInt(vecnm[0]);//配列n(前)
		int arraySizeS = Integer.parseInt(vecnm[1]);//配列m(後)

		//CはAとbの掛け算
		//for(int i =1;i<m;i++){
		//C +=A*b}

		//n*mである行列Aの計算
		int[][] A = new int[n][arraySizeS];//Aの要素nとm
		String[] strArrayT = null; //実行データ用　文字列として使っているため0でなくnull
		for (int i = 0; i < n; i++) {//nのループ
			strArrayT = (String_spot.readLine()).split("\\s");//入力を半角スペースで分轄
			for (int j = 0; j < arraySizeS; j++) {//mのループ
				A[i][j] = Integer.parseInt(strArrayT[j]);//文字列から数値に変換
			}
		}

		//m*1であるベクトルbの計算
		int[] total_n = new int[arraySizeS];//bの要素m
		for (int k = 0; k < arraySizeS; k++) {
			total_n[k] = Integer.parseInt(String_spot.readLine());//文字列から数値に変換

		}

		//A*bの積C
		for (int strSub = 0; strSub < n; strSub++) {
			int minConst = 0;//合計の初期化
			for (int s = 0; s < arraySizeS; s++){
				minConst += (A[strSub][s] * total_n[s]);
			}
			System.out.println(minConst);//出力
		}
	}
}

