        long pro(long a, long gosen_bill) {
            return (a % mod * gosen_bill % mod) % mod;
        }

        long add(long a, long b) {
            return (a + b) % mod;
        }

        long ncr3(long n) {
            return (n * (n - 1) * (n - 2)) / 6l;
        }

        long ncr2(long n) {
            return n * (n - 1) / 2l;
        }

        long modPow(long x, long y) {
            long strr = 1l;
            x = x % mod;
            while (y > 0) {
                if (y % 2 != 0)
                    strr = pro(strr, x);
                x = pro(x, x);
                y = y >> 1;
            }
            return strr;
