		long cnt = 0;
		String pre = null;
		long cat = 1;
		for(String s : sArray) {
			if(pre == null) {
				pre = s;
				continue;
			}
			if(!pre.equals(s)) {
				cnt += count(cat);
				cat = 1;
			} else {
				cat++;
			}
			pre = s;
		}
		cnt += count(cat);
		System.out.println(cnt);
		sc.close();

	}

	private static long count(long n) {
		long ret = 0;
		for(long i = 1 ; i <= n ; i++) {
			ret += (n - i);
		}
		return ret;
	}
}

