class Main {
  public static void main(String[] args) {
    Set<Integer> ori = new HashSet<>();
    Scanner reds = new Scanner(System.in);
    int x = reds.nextInt();
    int inputArr = reds.nextInt();
    int[] count_ABC = new int[inputArr];
    for(int i = 0; i < inputArr; i++)
      count_ABC[i] = reds.nextInt();

    Arrays.sort(count_ABC);
    int diff = 0, flag = 0, returnNum = 0;
    while(flag == 0) {
      if(Arrays.binarySearch(count_ABC, x-diff) < 0) {
        returnNum = x - diff;
        flag = 1;
      } else if(Arrays.binarySearch(count_ABC, x+diff) < 0) {
        returnNum = x + diff;
        flag = 1;
      }
      diff++;
    }
    System.out.println(returnNum);
  }
}

