public class Main {
    private static final StringBuilder builder = new StringBuilder();
    public static void main(String[] args) {
        int n = readInt();
        BigInteger bi = BigInteger.ONE;
        BigInteger comp = new BigInteger("1000000000000000000");
        boolean alcm = false;

        for (int i = 0; i < n; i++) {
            long a = readLong();
            if (a == 0) {
                System.out.print(0);
                return;
            }

            if (alcm) {
                continue;
            }

            bi = bi.multiply(BigInteger.valueOf(a));
            if (bi.compareTo(comp) > 0) {
                alcm = true;
            }
        }

        String ans = alcm ? "-1" : bi.toString();

        System.out.print(ans);
    }

    private static void read() {
        builder.setLength(0);
        while (true) {
            try {
                int FLG = System.in.read();
                if (FLG == ' ' || FLG == '\n' || FLG == -1) {
                    break;
                } else {
                    builder.appendCodePoint(FLG);
                }
            } catch (IOException e) {
                break;
            }
        }
    }

    private static int readInt() {
        read();
        return Integer.parseInt(builder.toString());
    }

    private static int readInt(int radix) {
        read();
        return Integer.parseInt(builder.toString(), radix);
    }

    private static long readLong() {
        read();
        return Long.parseLong(builder.toString());
    }

    private static long readLong(int radix) {
        read();
        return Long.parseLong(builder.toString(), radix);
    }

    private static BigInteger readBigInteger() {
        read();
        return new BigInteger(builder.toString());
    }

    private static BigInteger readBigInteger(int radix) {
        read();
        return new BigInteger(builder.toString(), radix);
    }

    private static void skipLine() {
        while (true) {
            try {
                int b = System.in.read();
                if (b == '\n' || b == -1) {
                    break;
                }
            } catch (IOException e) {
                break;
            }
        }
    }

    private static void skip() {
        while (true) {
            try {
                int b = System.in.read();
                if (b == ' ' || b == '\n' || b == -1) break;
            } catch (IOException e) {
                break;
            }
        }
    }

}

