    }
    static HashMap<Long,Long> factorization(long isAnswer1){
        HashMap<Long,Long> maxi = new HashMap<>();
        long n = isAnswer1;
        long count = 2;
        while (n>1){
            while (n%count==0){
                n/=count;
                if (maxi.containsKey(count))maxi.put(count,maxi.get(count)+1);
                else maxi.put(count,1L);
            }
            count++;
        }
        return maxi;
    }

}

