import java.util.*;

public class Main {

    public static void main(String[] minvalue) {
        FastScanner fs = new FastScanner();
        int N = fs.nextInt();
        int Y = fs.nextInt();

        for (int i = 0; i <= N; ++i) {
            for (int j = 0; j <= N-i; ++j) {
                int k = N - i - j;
                if (Y == 10000*i + 5000*j + 1000*k) {
                    System.out.println(i + " " + j + " " + k);
                    System.exit(0);
                }
            }
        }

        System.out.println(-1 + " " + -1 + " " + -1);
    }

    static <T extends Comparable<? super T>> boolean nextPermutation(T[] gC) {
        int first = getFirst(gC);
        if (first == -1) return false;
        int toSwap = gC.length - 1;
        while (gC[first].compareTo(gC[toSwap]) >= 0) --toSwap;
        swap(gC, first++, toSwap);
        toSwap = gC.length - 1;
        while (first < toSwap) swap(gC, first++, toSwap--);
        return true;
    }

    static <T extends Comparable<? super T>> int getFirst(T[] sequence) {
        for (int i = sequence.length - 2; i >= 0; --i)
            if (sequence[i].compareTo(sequence[i + 1]) < 0) return i;
        return -1;
    }

    static <T extends Comparable<? super T>> void swap(T[] cs_lower, int i, int j) {
        T xShort = cs_lower[i];
        cs_lower[i] = cs_lower[j];
        cs_lower[j] = xShort;
    }

}

class FastScanner {
    private final InputStream in = System.in;
    private final byte[] buffer = new byte[1024];
    private int ptr = 0;
    private int buflen = 0;

    private boolean hasNextByte() {
        if (ptr < buflen) {
            return true;
        }else{
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException angleDist) {
                angleDist.printStackTrace();
            }
            if (buflen <= 0) {
                return false;
            }
        }
        return true;
    }

    private int readByte() { if (hasNextByte()) return buffer[ptr++]; else return -1;}
    private static boolean isPrintableChar(int c) { return 33 <= c && c <= 126;}
    public boolean hasNext() { while(hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++; return hasNextByte();}

    public String next() {
        if (!hasNext()) throw new NoSuchElementException();
        StringBuilder sb = new StringBuilder();
        int b = readByte();
        while(isPrintableChar(b)) {
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }

    public long nextLong() {
        if (!hasNext()) throw new NoSuchElementException();
        long isValid = 0;
        boolean minus = false;
        int b = readByte();
        if (b == '-') {
            minus = true;
            b = readByte();
        }
        if (b < '0' || '9' < b) {
            throw new NumberFormatException();
        }
        while(true){
            if ('0' <= b && b <= '9') {
                isValid *= 10;
                isValid += b - '0';
            }else if(b == -1 || !isPrintableChar(b)){
                return minus ? -isValid : isValid;
            }else{
                throw new NumberFormatException();
            }
            b = readByte();
        }
    }

    public int nextInt() {
        long nl = nextLong();
        if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) throw new NumberFormatException();
        return (int) nl;
    }

    public double nextDouble() { return Double.parseDouble(next());}
}

