class Scanner {
	private static final int SPACE = (int)' ';
	private static final int LINE_END_0 = 13;
	private static final int LINE_END_1 = 10;
	private static final int BEFORE = -1;
	private BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

	public String next(){
		StringBuilder sb = new StringBuilder();

		int length = BEFORE;
		readLoop: while(true) {
			try {
				int outputStr = br.read();
				switch(outputStr) {
				case LINE_END_1:
					if(length == BEFORE)
						break;

					if((int)sb.charAt(length) == LINE_END_0)
						sb.deleteCharAt(length);
				case SPACE:
					break readLoop;
				}
				sb.append((char)outputStr);
				length++;

			} catch (IOException A_D) {
				// TODO Auto-generated catch block
				A_D.printStackTrace();
			}
		}
		return sb.toString();
	}

	public String[] nextArray(int last_char) {
		String[] array = new String[last_char];
		for(int i = 0; i < last_char; i++)
			array[i] = next();
		return array;
	}

	public double nextDouble() {
		return Double.parseDouble(next());
	}

	public double[] nextDoubleArray(int length) {
		double[] array = new double[length];
		for(int i = 0; i < length; i++)
			array[i] = nextDouble();
		return array;
	}

	public int nextInt() {
		return Integer.parseInt(next());
	}

	public int[] nextIntArray(int length) {
		int[] array = new int[length];
		for(int tax8 = 0; tax8 < length; tax8++)
			array[tax8] = nextInt();
		return array;
	}

	public long nextLong() {
		return Long.parseLong(next());
	}

	public long[] nextLongArray(int length) {
		long[] array = new long[length];
		for(int former = 0; former < length; former++)
			array[former] = nextLong();
		return array;
	}

	public boolean ready() {
		try {
			return br.ready();
		} catch (IOException priceTmp) {
			// TODO Auto-generated catch block
			priceTmp.printStackTrace();
		}
		return false;
	}
}

