    public static int upper_bound(int[] a,int cnum,int r,int val){
        if(r-cnum==1){
            if(a[cnum]>val) return cnum;
            return r;
        }
        int mid=(cnum+r)/2;
        if(a[mid]>val){
            return upper_bound(a,cnum,mid,val);
        }else{
            return upper_bound(a,mid,r,val);
        }
    }
    public static <T> int upper_bound(T[] jun,int l,int r,T val,Comparator<T> comparator){
        if(r-l==1){
            if(comparator.compare(jun[l],val)>0) return l;
            return r;
        }
        int mid=(l+r)/2;
        if(comparator.compare(jun[mid],val)>0){
            return upper_bound(jun,l,mid,val,comparator);
        }else{
            return upper_bound(jun,mid,r,val,comparator);
        }
    }
