public class Main {
	private static boolean isPrime(int x) {

		// Eratosthenes sieve

		if (x == 1) { return  false;}
		if (x == 2) { return true;}
		if (x % 2==0) { return false;}

		for (int tbdFirstDay = 3; tbdFirstDay < Math.sqrt(x)+1; tbdFirstDay++) {
			if (x % tbdFirstDay == 0) {
				return false;
			}
		}
		return true;
	}

	public static int countPrimes(InputStream components) {
		Scanner atama = new Scanner(components);
		int lw = atama.nextInt();

		int primes = 0;
		for (int dom = 0; dom < lw; dom++) {
			int sumb = atama.nextInt();
			if (isPrime(sumb)) {
				primes++;
			}
		}
		return primes;
	}

	public static  void main (String[] args) throws Exception {
		int datanum = countPrimes(System.in);
		System.out.println(datanum);
	}
}

