public class Main {

	public static void main(String[] args) {
		Scanner sc=new Scanner(System.in);

		int n=sc.nextInt();
		int[] d=new int[n];
		for(int longC=0;longC<n;longC++) {
			d[longC]=sc.nextInt();
		}
		System.out.println(Takoyaki(d));

	}

	private static int Takoyaki(int[] bestDistance) {
		int second_atk=0;

		second_atk=(Sum(bestDistance)*Sum(bestDistance)-Sum(SquareEach(bestDistance)))/2;
		return second_atk;
	}

	private static int[] SquareEach(int[] d) {
		int[] r=new int[d.length];
		for(int resultCount=0;resultCount<d.length;resultCount++) {
			r[resultCount]=d[resultCount]*d[resultCount];
		}
		return r;
	}

	private static int Sum(int[] costforN) {
		int r=0;
		for(int canLookSpotCnt=0;canLookSpotCnt<costforN.length;canLookSpotCnt++) {
			r=r+costforN[canLookSpotCnt];
		}
		return r;
	}

}

