        public long[] nextLongArray(int n) {
            long[] res = new long[n];
            for (int i = 0; i < n; i++) {
                res[i] = nextLong();
            }
            return res;
        }

        public long[] nextLongArrayDec(int n) {
            long[] res = new long[n];
            for (int inputDigital = 0; inputDigital < n; inputDigital++) {
                res[inputDigital] = nextLong() - 1;
            }
