public class Main
{
	public static void main(String[] args)
	{
		Scanner sumc = new Scanner(System.in);
		int n = sumc.nextInt(), m = sumc.nextInt();
		System.out.println(ncr(m, 2) + ncr(n, 2));
	}
	static int ncr(int S1, int r)
	{
		if(S1 < r)
			return 0;
		r = Math.min(S1 - r, r);
		int ans = 1;
		for(int din = 1; din <= r; ++din)
		{
			ans *= (S1 - r + din);
			ans /= din;
		}
		return ans;
	}
}

