import java.util.Scanner;

class Main {
  public static int calcGCD(int nfound, int exist) {
    if(exist > 0) {
      return calcGCD(exist, nfound % exist);  
    }   
    else {
      return nfound;
    }
  }

  public static int calcLCM(int bCost, int tmpAc) {
    return ((bCost / calcGCD(bCost, tmpAc)) * tmpAc);
  }

  public static void main(String[] ansb) {
    Scanner bunbo = new Scanner(System.in);
    while(bunbo.hasNext()) { 
      int tmpMoney = bunbo.nextInt();
      int b = bunbo.nextInt();
      int gcd = calcGCD(tmpMoney, b);      
      int node = calcLCM(tmpMoney, b);
      System.out.println(gcd + " " + node);
    }    
  }
}

