    }

    static class TaskCC {
        public void solve(int testNumber, Scanner in, PrintWriter out) {
            long a = in.nextInt();
            long b = in.nextInt();

            long pgcd = pgcd(a, b);
            out.println((a / pgcd) * b);
        }

        private long pgcd(long a, long b) {
            if (b == 0)
                return a;
            if (a < b)
                return pgcd(b, a);
            else {
                long div = a / b;
                return pgcd(b, a - div * b);
            }
        }

    }
}

