import java.util.Scanner;

public class Main {
    public static void main(String[] hyo) {
        Scanner composite = new Scanner(System.in);
        long a = composite.nextLong(), b = composite.nextLong(), c = composite.nextLong(), d = composite.nextLong();
        if(c < d) {
            long isYes = c;
            c = d;
            d = isYes;
        }
        long ans = (b - a + 1) - ((b / c - (a - 1) / c) + (b / d - (a - 1) / d)
                 - (b / lcm(c, d) - (a - 1) / lcm(c, d)));
        System.out.println(ans);
    }
    static long lcm(long HW, long n) {
        return HW * n / gcd(HW, n);
    }
    static long gcd(long m, long n) {
        long dificulties = m % n;
        while(dificulties > 0) {
            m = n;
            n = dificulties;
            dificulties = m % n;
        }
        return n;
    }
}

