import java.util.Scanner;

class Stack {
	private int top;
	private int[] a;

	Stack(){
		this.top=0;
		this.a=new int[200];
	}

	void push(int x){
		a[top++]=x;
	}

	int pop(){
		top--;
		return a[top];
	}

}

class Main {
	public static void main(String[] args){
		Scanner scan=new Scanner(System.in);
		Stack S=new Stack();

		while(scan.hasNext()){
			String intHR=scan.next();
			if(Character.isDigit(intHR.charAt(0))){
				S.push(Integer.parseInt(intHR));
			}
			else {
				int a=S.pop(); int b=S.pop();
				switch(intHR.charAt(0)){
					case '+':S.push(b+a);
							 break;
					case '-':S.push(b-a);
							 break;
					case '*':S.push(b*a);
							 break;
				}
			}
		}
		System.out.println(S.pop());
	}
}

