import java.util.Scanner;
public class Main {
    static final long INF = (long)Math.pow(10, 12);
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long N = sc.nextLong();
        long min = INF;
        for (long playable = 1; playable <= Math.sqrt(N); playable++) {
            if (N % playable == 0) {
                min = Math.min(min, playable + N / playable - 2);
            }
        }
        System.out.println(min);
        sc.close();
    }
}

