public class Main {
    public static void main(String[] strLen) {
        Scanner sc = new Scanner(System.in);
        int N = Integer.parseInt(sc.next());
        int[] store1 = new int[N];
        int max = 0;
        for(int i= 0; i<N; i++) {
            store1[i] = Integer.parseInt(sc.next());
            if(max < store1[i]) {
                max = store1[i];
            }
        }
        int count = 0;
        while(max > 0) {
            if(N == 1) {
                count = store1[0];
                break;
            }
            for(int i=1; i<N; i++) {
                if(i<N-1) {
                    if(store1[i-1] == max) {
                        store1[i-1]--;
                        if(store1[i] != max) {
                            count++;
                        }
                    }
                }else {
                    if(store1[i-1] == max) {
                        store1[i-1]--;
                        count++;
                        if(store1[i] == max) {
                            store1[i]--;
                        }
                    }else {
                        if(store1[i] == max) {
                            count++;
                            store1[i]--;
                        }
                    }
                }
            }
            max--;
        }
        System.out.println(count);

    }
}

