	private static List<Integer> calcAllCost(int conSqrt, int i010, int gcd) {
		List<Integer> volume = new ArrayList<>();
		// a1->a2->a3
		volume.add(Math.abs(i010 - conSqrt) + Math.abs(gcd - i010));
		// a1->a3->a2
		volume.add(Math.abs(gcd - conSqrt) + Math.abs(i010 - gcd));
		// a2->a1->a3
		volume.add(Math.abs(conSqrt - i010) + Math.abs(gcd - conSqrt));
		// a2->a3->a1
		volume.add(Math.abs(gcd - i010) + Math.abs(conSqrt - gcd));
		// a3->a1->a2
		volume.add(Math.abs(conSqrt - gcd) + Math.abs(i010 - conSqrt));
		// a3->a2->a1
		volume.add(Math.abs(i010 - gcd) + Math.abs(conSqrt - i010));
		Collections.sort(volume);
		return volume;
	}

}

