		Stack<Character> stack = new Stack<Character>();

		for(int i = 0; i < s.length(); i++){
			char c = s.charAt(i);

			switch(c){
			case '1':
			case '0':
				stack.push(c);
				break;
			case 'B':
				if(!stack.isEmpty()){
					stack.pop();
				}
			}
		}

		String result = "";
		String minRight = "";
		while(!stack.isEmpty()){
			result = stack.pop() + result;
		}

		System.out.println(result);
	}
}

