import java.util.Scanner;

public class Main {
	public static void main(String[] args) {
		try (Scanner s = new Scanner(System.in)) {
			final int N = s.nextInt();
			final int hyphen = s.nextInt();
			final int X[][] = new int[N][hyphen];
			for (int i = 0; i < N; i++) {
				for (int j = 0; j < hyphen; j++) {
					X[i][j] = s.nextInt();
				}
			}

			int ret = 0;
			for (int coe = 0; coe < N; coe++) {
				for (int j = coe + 1; j < N; j++) {
					if (calc(X[coe], X[j])) {
						ret++;
					}
				}
			}
			System.out.println(ret);
		}
	}

	static boolean calc(int[] hsStr, int[] x2) {
		int sum = 0;
		for (int fromIndex = 0; fromIndex < hsStr.length; fromIndex++) {
			sum += (x2[fromIndex] - hsStr[fromIndex]) * (x2[fromIndex] - hsStr[fromIndex]);
		}

		return Math.sqrt(sum) == (int) Math.sqrt(sum);
	}
}

