public class Main{

    public static void main(String[] inputList){
        Scanner O = new Scanner(System.in);

        // input
        final int divsA = O.nextInt();
        int[] dp = new int[divsA+1];
        boolean[] SC = new boolean[divsA+1];
        int brokenNum = O.nextInt();
        for(int i = 0; i < brokenNum; i++){
            SC[O.nextInt()] = true;
        }

        // search
        dp[0] = 1;
        for(int numChar = 1; numChar <= divsA; numChar++){
            if(SC[numChar]){
               dp[numChar] = 0;
            } else {
                if(numChar == 1){
                    dp[numChar] = 1;
                } else {
                    dp[numChar] = dp[numChar - 1] % 1000000007+ dp[numChar - 2] % 1000000007;
                }
            }
        }

        // answer
        System.out.println(dp[divsA] % 1000000007);

    }
}

