		boolean[] ac = new boolean[N];
		Arrays.fill(ac, false);

		boolean[] b = new boolean[N];
		for(int i=0;i<M;i++) {
			if(S[i].equals("AC")) {
				b[p[i]] = true;
			}
		}


		int numOfWA = 0;
		int numOfAC = 0;

		for (int i = 0; i < M; i++) {
			if (S[i].equals("AC")) {
				if (!ac[p[i]]) { //AC済みでないなら
					numOfAC++;
					ac[p[i]] = true;
				}
				//AC済みならすでにカウントされているので何もしない

			} else { // WA
				if (!ac[p[i]] && b[p[i]]) { //AC済みでないなら
					numOfWA++; //ペナルティを増やす
				}
				//AC済みならペナルティなし
			}
		}

		out.println(numOfAC + " " + numOfWA);

	}

	public static void main(String[] args) {
		new Main()._main(args);
	}
}

